#include <limits.h>

#define INF INT_MAX

void dijkstra(int V, int g[V][V], int src, int dist[], int parent[]) {
  int done[V];
  for (int i = 0; i < V; i++) { dist[i] = INF; done[i] = 0; parent[i] = -1; }
  dist[src] = 0;
  for (int round = 0; round < V; round++) {
    int u = -1;
    for (int v = 0; v < V; v++)
      if (!done[v] && (u == -1 || dist[v] < dist[u])) u = v;
    if (u == -1 || dist[u] == INF) break;   /* the rest is unreachable */
    done[u] = 1;
    for (int v = 0; v < V; v++) {
      if (g[u][v] && !done[v] && dist[u] + g[u][v] < dist[v]) {
        dist[v] = dist[u] + g[u][v];
        parent[v] = u;
      }
    }
  }
}

typedef struct { int d, v; } Item;          /* (distance, vertex) */
typedef struct { Item *a; int n; } Heap;

static void swap(Item *x, Item *y) { Item t = *x; *x = *y; *y = t; }

void push(Heap *h, int d, int v) {            /* capacity >= E + 1 */
  int i = h->n++;
  h->a[i] = (Item){ d, v };
  while (i > 0 && h->a[(i - 1) / 2].d > h->a[i].d) {
    swap(&h->a[i], &h->a[(i - 1) / 2]);
    i = (i - 1) / 2;
  }
}

Item pop(Heap *h) {
  Item top = h->a[0];
  h->a[0] = h->a[--h->n];
  int i = 0;
  for (;;) {
    int l = 2 * i + 1, r = l + 1, m = i;
    if (l < h->n && h->a[l].d < h->a[m].d) m = l;
    if (r < h->n && h->a[r].d < h->a[m].d) m = r;
    if (m == i) break;
    swap(&h->a[i], &h->a[m]);
    i = m;
  }
  return top;
}

typedef struct Edge { int to, w; struct Edge *next; } Edge;

void dijkstra_heap(int V, Edge *adj[], int src, int dist[], int parent[], Heap *h) {
  for (int i = 0; i < V; i++) { dist[i] = INT_MAX; parent[i] = -1; }
  dist[src] = 0;
  push(h, 0, src);
  while (h->n > 0) {
    Item cur = pop(h);
    if (cur.d > dist[cur.v]) continue;          /* stale entry */
    for (Edge *e = adj[cur.v]; e; e = e->next) {
      int nd = cur.d + e->w;
      if (nd < dist[e->to]) {
        dist[e->to] = nd;
        parent[e->to] = cur.v;
        push(h, nd, e->to);
      }
    }
  }
}

void print_path(int parent[], int target) {
  if (target == -1) return;
  print_path(parent, parent[target]);
  printf("%d ", target);
}
